package com.bhojbangla.customer;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.UUID;import com.bhojbangla.security.JwtService;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class CustomerExperienceIntegrationTest{
 @Autowired MockMvc mvc;@Autowired JwtService jwt;
 @Test void registrationCreatesCustomerOnlyAndRefreshCookieIsHttpOnly()throws Exception{String email="phase2-"+UUID.randomUUID()+"@example.test";mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"customer-secure-passphrase\"}" )).andExpect(status().isOk()).andExpect(jsonPath("$.role").value("CUSTOMER")).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("HttpOnly")));}
 @Test void rejectsBadCredentialsAndInvalidInput()throws Exception{mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"missing@example.test\",\"password\":\"wrong-secure-password\"}")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"bad\",\"password\":\"short\"}")).andExpect(status().isBadRequest());}
 @Test void coverageReturnsOnlyEnabledDistrictAndCoverageRecords()throws Exception{mvc.perform(get("/api/coverage/districts")).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Dhaka")).andExpect(jsonPath("$[0].id").isNumber()).andExpect(jsonPath("$.length()").value(1));}
 @Test void orderEndpointRequiresCustomerAndStillRejectsUnverifiedOrdering()throws Exception{String body="{\"restaurantId\":1,\"items\":[{\"menuItemId\":1,\"quantity\":1}],\"district\":\"Dhaka\",\"city\":\"Dhaka\",\"address\":\"Road 1\",\"phone\":\"01700000000\",\"paymentMethod\":\"COD\"}";mvc.perform(post("/api/orders").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isUnauthorized());mvc.perform(post("/api/orders").header("Authorization","Bearer "+jwt.issue("rider@example.test","RIDER")).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post("/api/orders").header("Authorization","Bearer "+jwt.issue("customer@example.test","CUSTOMER")).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isServiceUnavailable());}
}

